CREATE TABLE qhr_employee_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,tax_code varchar(40),social_insurance_no varchar(40),bank_account varchar(80),timekeeping_code varchar(80),lifecycle_status varchar(40) NOT NULL DEFAULT 'probation',branch_id uuid,department_id uuid,position_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,employee_id));
CREATE INDEX qhr_employee_profiles_org_idx ON qhr_employee_profiles(org_id,lifecycle_status);
CREATE TABLE qhr_employment_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,contract_type varchar(40) NOT NULL,contract_no varchar(80),branch_id uuid,start_date date NOT NULL,end_date date,status varchar(40) NOT NULL DEFAULT 'draft',revision int NOT NULL DEFAULT 0,legal_reviewer_id uuid,signed_at timestamptz,workflow_instance_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_employment_contracts_org_idx ON qhr_employment_contracts(org_id,status);
CREATE TABLE qhr_contract_annexes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,contract_id uuid NOT NULL REFERENCES qhr_employment_contracts(id),employee_id uuid NOT NULL,annex_type varchar(40) NOT NULL,content jsonb NOT NULL DEFAULT '{}',effective_date date,status varchar(40) NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_contract_annexes_org_idx ON qhr_contract_annexes(org_id,contract_id);
CREATE TABLE qhr_contract_tracking_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,contract_id uuid NOT NULL REFERENCES qhr_employment_contracts(id),event varchar(40) NOT NULL,actor_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),note text,seq int NOT NULL);
CREATE INDEX qhr_contract_tracking_events_org_idx ON qhr_contract_tracking_events(org_id,contract_id,seq);
CREATE TABLE qhr_contract_expiry_watches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,contract_id uuid NOT NULL REFERENCES qhr_employment_contracts(id),employee_id uuid NOT NULL,expiry_date date NOT NULL,notified_at timestamptz,action_taken varchar(40),handled_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,contract_id));
CREATE INDEX qhr_contract_expiry_watches_org_idx ON qhr_contract_expiry_watches(org_id,expiry_date,notified_at);
CREATE TABLE qhr_transfer_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,from_department_id uuid,to_department_id uuid,from_position_id uuid,to_position_id uuid,from_branch_id uuid,to_branch_id uuid,reason text,effective_date date NOT NULL,status varchar(40) NOT NULL DEFAULT 'pending',workflow_instance_id uuid,rejection_reason text,bhxh_required boolean NOT NULL DEFAULT false,contract_action varchar(40),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_transfer_requests_org_idx ON qhr_transfer_requests(org_id,status);
CREATE TABLE qhr_transfer_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,transfer_request_id uuid NOT NULL REFERENCES qhr_transfer_requests(id),decision_no varchar(80),signed_by uuid,signed_at timestamptz,salary_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_transfer_decisions_org_idx ON qhr_transfer_decisions(org_id,transfer_request_id);
CREATE TABLE qhr_business_trip_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,purpose text,destination text,start_date date NOT NULL,end_date date NOT NULL,status varchar(40) NOT NULL DEFAULT 'pending',workflow_instance_id uuid,advance_requested_at timestamptz,settled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_business_trip_requests_org_idx ON qhr_business_trip_requests(org_id,status);
CREATE TABLE qhr_business_trip_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,trip_request_id uuid NOT NULL REFERENCES qhr_business_trip_requests(id),seq int NOT NULL,from_place text,to_place text,depart_at timestamptz,arrive_at timestamptz,note text);
CREATE INDEX qhr_business_trip_routes_org_idx ON qhr_business_trip_routes(org_id,trip_request_id,seq);
CREATE TABLE qhr_trip_logistics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,trip_request_id uuid NOT NULL REFERENCES qhr_business_trip_requests(id),kind varchar(40) NOT NULL,provider text,cost numeric(20,2),status varchar(40) NOT NULL DEFAULT 'planned',details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_trip_logistics_org_idx ON qhr_trip_logistics(org_id,trip_request_id,kind);
